import sys
input = sys.stdin.readline
sys.setrecursionlimit(10 ** 7)
t = int(input())
for _ in range(t):
	n = int(input())
	I = list(map(int, input().split()))
	Ans = [-1] * 3
	check = True
	A1 = [1, 2, 4, 8]
	A2 = [3, 6, 7, 9]
	for num in I:
		if num % 10 == 0:
			if Ans[2] == -1:
				Ans[2] = num
			elif Ans[2] != num:
				check = False
				break
		elif num % 10 == 5:
			if Ans[2] == -1:
				Ans[2] = num + 5
			elif Ans[2] != num + 5:
				check = False
				break
		elif num % 10 in A1:
			if num % 20 < 10:
				Ans[0] = 1
			else:
				Ans[1] = 1
		elif num % 20 < 10:
			Ans[1] = 1
		else:
			Ans[0] = 1
	cnt = 0
	for i in Ans:
		if i == -1:
			cnt += 1
	if cnt != 2:
		check = False
	if check:
		print('Yes')
	else:
		print('No')
